<script setup lang="ts">import {ref,computed} from 'vue';import PageHeading from '../components/common/PageHeading.vue';import RunList from '../components/RunList.vue';import Notice from '../components/common/Notice.vue';import {useTask} from '../hooks/useTask';import {researchApi} from '../api/research';const p=defineProps<{studies:any[];specimens:any[];runs:any[];user:any;reloadResearch:()=>Promise<void>}>(),emit=defineEmits(['open']);const id=ref(0),name=ref('整芯成组一致性 '+new Date().toLocaleTimeString()),B=ref(400),seed=ref(231),task=useTask(),study=computed(()=>p.studies.find(s=>s.id===(id.value||p.studies[0]?.id))),items=computed(()=>p.specimens.filter(s=>(s.study_id as number)===study.value?.id)),N=computed(()=>items.value.length),labels=computed(()=>items.value.map((s:any)=>((s.core||'') as string).trim())),hasAnyCore=computed(()=>labels.value.some(Boolean)),complete=computed(()=>labels.value.every(Boolean)),hasCores=computed(()=>hasAnyCore.value&&complete.value),cores=computed(()=>[...new Set(labels.value.filter(Boolean))]),sizes=computed(()=>{const m:Record<string,number>={};labels.value.forEach((c:string)=>{if(c)m[c]=(m[c]||0)+1});return Object.values(m)}),sizeText=computed(()=>[...new Set(sizes.value)].sort((a,b)=>a-b).join(' / ')),unequal=computed(()=>new Set(sizes.value).size>1);async function run(){await task.act(async()=>{const r=await researchApi.createRun({study_id:study.value.id,name:name.value,bootstrap_repeats:B.value,seed:seed.value,panel_scope:'fixed_three_raters'});await p.reloadResearch();emit('open',r)},'κ与重采样已排队')}</script><template><PageHeading index="03" :title="hasCores?'整芯成组，携带全部试样。':'固定面板，逐试样重采样。'" description="参数在运行前确定；有岩芯字段时整芯有放回抽原数量岩芯，否则逐试样；不按单票重采样。"/><div class="config-layout"><form class="input-sheet" @submit.prevent="run"><label>拟合研究<select :value="study?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="s in studies" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>运行名称<input v-model="name" required/></label><div class="field-pair"><label>bootstrap重复 B<input v-model.number="B" type="number" min="400" max="1000" required/></label><label>随机种子 seed<input v-model.number="seed" type="number" min="0" max="1000000000" required/></label></div><p v-if="hasCores">本研究{{cores.length}}个岩芯 / {{N}}个试样，组大小 {{sizeText}}{{unequal?'（不等组；点估计仍按原逐票每个试样行等权）':''}}；{{study?.raters.join(' / ')}}固定面板。每次有放回抽 {{cores.length}} 个岩芯，携带全部试样，重复抽中保留倍数。</p><p v-else-if="hasAnyCore">本研究{{N}}个试样，但岩芯编号不完整（{{labels.filter(Boolean).length}}/{{N}} 已填）。补齐全部岩芯或全部留空后才能运行。</p><p v-else>本研究{{N}}个试样，{{study?.raters.join(' / ')}}固定面板。无岩芯字段，沿用逐试样重采样。经验区间95%，线性percentile；有效比例≥90%才报告。</p><p v-if="hasAnyCore&&!complete" class="invalid-reason">岩芯分组不完整：全部试样须填写岩芯编号，或全部留空；否则运行会被拒绝。</p><p v-if="hasCores&&cores.length<2" class="invalid-reason">岩芯组不足两组，按岩芯重采样会被拒绝。</p><button v-if="user.role!=='viewer'" class="primary" :disabled="task.state.busy||!study">送入κ与bootstrap队列 →</button><p v-else>观察员只读已有研究。</p><Notice v-bind="task.state"/></form><aside class="method-note"><small>AGREEMENT / NOT ACCURACY</small><h2>κ = (P̄ − Pe)<br/>÷ (1 − Pe)</h2><p>Pᵢ按同一试样的成对一致计算，Pe来自全部票的类别基率。</p><p>Pe=1时κ未定义。全同类不能标κ1；全一致且多类别时可以κ1。</p><p>同一岩芯切出的试样不独立。每次有放回抽原数量岩芯，整芯携带全部试样；重复抽中保留倍数。退化重复保留原因及数量，未补抽。</p></aside></div><section class="section"><h2>核算队列与归档</h2><RunList :runs="runs" @open="emit('open',$event)"/></section></template>
